records.sql:
SELECT SUM(CASE WHEN move_type = 'out_refund' THEN -ABS(amount) ELSE ABS(amount) END) AS net_billed_usd
FROM intermediate.int_invoices
WHERE move_type IN ('out_invoice', 'out_refund');

